public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int CH, isEven, z, GCD, GCD_n;
    CH = sc.nextInt();
    isEven = sc.nextInt();
    if (CH < isEven) { //swap
      z = CH;
      CH = isEven;
      isEven = z;
    }
    GCD = isEven;
    GCD_n = CH % GCD;
    while(GCD_n != 0) {
      CH = GCD;
      GCD = GCD_n;
      GCD_n = CH % GCD;
    }
    System.out.println(GCD);
    sc.close();
  }
}

