public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		int result3 = sc.nextInt();
		int fourth = sc.nextInt();

		System.out.println(euclideanAlgorithm(result3, fourth));
	}

	public static int euclideanAlgorithm(int result3, int fourth) {
		int isPrime1;
		while (true) {
			isPrime1 = result3 % fourth;
			if (isPrime1 == 0) {
				return fourth;
			}
			result3 = fourth;
			fourth = isPrime1;
		}
	}
}

