class GreatestCommonDivisor{
    // int GCD;    //Greatest Common Divisor 
    public int getGCD(int maxNum, int minNum){
        if(minNum == 0){
            return maxNum;
        }else{
            return getGCD(minNum, (maxNum % minNum));
        }
    }
}

import java.util.Scanner;

class MathUtil {
	public static long gcd(long x, long TD) {
		if(x == 0) return TD;
		if(TD == 0) return x;
		if(x >= TD) {
			return gcd(TD, x % TD);
		} else {
			return gcd(x, TD % x);
		}
	}
}

