import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        String strX = scan.next();
        String TcharArray = scan.next();

        int x = Integer.parseInt(strX);
        int profitT = Integer.parseInt(TcharArray);

        int answer = divisor(x, profitT);

        System.out.println(answer);
        scan.close();
    }

    static int divisor(int x, int profitT) {
        if (profitT > x) {
            return divisor(profitT, x);
        }
        while (profitT != 0) {
            int remainder = x % profitT;
            x = profitT;
            profitT = remainder;
        }
        return x;
    }
}

