	}

  }
  public static String select(String inputnum){
	String space = " ";
	String nums[] = inputnum.split(space);
        int x = Integer.parseInt(nums[0]);
        int stdDeviation = Integer.parseInt(nums[1]);

        if(x > stdDeviation){
		int temp = x;
		x = stdDeviation;
		stdDeviation = temp;
		return(x + space + stdDeviation);
	}
	return(x + space + stdDeviation);
  }


}

