import java.util.Scanner;
import java.util.function.Function;

public class Main {

    public static void main(String[] args) {
        new Main().solve();
    }

    Scanner sc = new Scanner(System.in);

    void solve() {
        String str;
        while (true) {
            str = sc.nextLine();
            String[] nextLong = str.split(" ");
            int n = Integer.parseInt(nextLong[0]);
            int progNumLength = Integer.parseInt(nextLong[1]);
            if (isFin(n, progNumLength)) break;
            System.out.println(sim(n, progNumLength));
        }
    }

    int sim(int n, int progNumLength) {
        int cnt = 0;
        for (int i = 1; i <= n; ++i) {
            for (int j = i + 1; j <= n; ++j) {
                if (i == j) continue;
                int k = progNumLength - i - j;
                if (i == k || j == k) continue;
                if (j < k && k <= n) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    boolean isFin(int n, int progNumLength) {
        return n == 0 && progNumLength == 0;
    }

}

