public class Main {

	public void run(java.io.InputStream in, java.io.PrintStream out) {
		final java.util.Scanner sc = new java.util.Scanner(in);
		long[][] primeJudge;
		long[][] minID;
		long[][] r;
		int n, hit, x_5;

		n = sc.nextInt();
		hit = sc.nextInt();
		x_5 = sc.nextInt();
		primeJudge = new long[n][hit];
		minID = new long[hit][x_5];
		for (int i = 0; i < n; ++i)
		for (int one1 = 0; one1 < hit; ++one1) {
			primeJudge[i][one1] = sc.nextLong();
		}
		for (int i = 0; i < hit; ++i)
		for (int one1 = 0; one1 < x_5; ++one1){
			minID[i][one1] = sc.nextLong();
		}

		r = new long[n][x_5];
		for (int i = 0; i < n; ++i)
		for (int one1 = 0; one1 < x_5; ++one1) {
			r[i][one1] = 0;
			for (int k = 0; k < hit; ++k) {
				r[i][one1] += primeJudge[i][k] * minID[k][one1];
			}
		}

		for (int i = 0; i < n; ++i) {
			for (int one1 = 0; one1 < x_5; ++one1) {
				out.print(r[i][one1]);
				if (one1 + 1 == x_5) out.println();
				else out.print(" ");
			}
		}

		sc.close();
	}

	public static void main(String[] args) {
		(new Main()).run(System.in, System.out);
	}

}

