import static java.math.BigInteger.*;

public class Main {

	public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String TAX_RATE;
		while(!"0".equals(TAX_RATE = br.readLine())){
			System.out.println(sum(TAX_RATE));
		}
	}

	private static int sum(String TAX_RATE) {
		BigInteger isRain = new BigInteger(TAX_RATE);
		if(isRain.compareTo(TEN) < 0){
			return Integer.parseInt(isRain.toString());
		}else{
			return Integer.parseInt(isRain.remainder(TEN).toString()) + sum(isRain.divide(TEN).toString());
		}
	}
}

