    class FastScanner {
        BufferedReader br;
        StringTokenizer ral;

        public FastScanner(File f) {
            try {
                br = new BufferedReader(new FileReader(f));
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
        }

        public FastScanner(InputStream f) {
            br = new BufferedReader(new InputStreamReader(f));
        }

        String next() {
            while (ral == null || !ral.hasMoreTokens()) {
                String s = null;
                try {
                    s = br.readLine();
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (s == null)
                    return null;
                ral = new StringTokenizer(s);
            }
            return ral.nextToken();
        }

        boolean hasMoreTokens() {
            while (ral == null || !ral.hasMoreTokens()) {
                String s = null;
                try {
                    s = br.readLine();
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (s == null)
                    return false;
                ral = new StringTokenizer(s);
            }
            return true;
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int half) {
            int[] intHour = new int[half];
            for (int i = 0; i < half; i++) {
                intHour[i] = sc.nextInt();
            }
            return intHour;
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        long[] nextLongArray(int half) {
            long[] intHour = new long[half];
            for (int i = 0; i < half; i++) {
                intHour[i] = sc.nextLong();
            }
            return intHour;
        }

        BigInteger nextBigInteger() {
            return new BigInteger(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        double[] nextDoubleArray(int half) {
            double[] intHour = new double[half];
            for (int i = 0; i < half; i++) {
                intHour[i] = sc.nextDouble();
            }
            return intHour;
        }

    }

    public static void main(String[] args) {
        new Main().runIO();
    }
}

