public class Main {
    public static void main(String[] args) {
        Main main = new Main();
        main.run();
    }

    // 変数一覧
    int firstB;
    String[] ROUND_UP_UNIT;

    public void run() {
        // 入力情報取得
        Scanner strSplit = new Scanner(System.in);
        firstB = strSplit.nextInt();
        ROUND_UP_UNIT = new String[firstB];
        for (int is_operator = 0; is_operator < firstB; is_operator++) {
            ROUND_UP_UNIT[is_operator] = strSplit.next();
        }
        strSplit.close();

        // 解答処理
        solve();
    }

    private void solve() {
        ROUND_UP_UNIT = deduplication(ROUND_UP_UNIT);
        System.out.println(ROUND_UP_UNIT.length);
    }

    // 配列内の重複を排除
    private String[] deduplication(String[] ROUND_UP_UNIT) {
        Set<String> get_time = new LinkedHashSet<String>();
        for (int is_operator = 0; is_operator < ROUND_UP_UNIT.length; is_operator++) {
            get_time.add(ROUND_UP_UNIT[is_operator]);
        }
        String[] ret = get_time.toArray(new String[get_time.size()]);
        return ret;
    }
}

