        Scanner readLineInt = new Scanner(System.in);
        int subTime = readLineInt.nextInt();
        long inData = 0;
        int tmpGcd = 0;
        for (int big = 1; big <= subTime; big++){
            for (int max_value = 1; max_value <= subTime; max_value++){
                for (int MIN = 1; MIN <= subTime; MIN++){
                    tmpGcd = gcd(big, max_value);
                    inData += gcd(tmpGcd, MIN);
                }
            }
        }
        System.out.println(inData);

    }

    public static int gcd (int prevBuy, int Calculation){
        int b_list = 0;
        if (prevBuy == 0) return Calculation;
        if (Calculation == 0) return prevBuy;
        if (prevBuy > Calculation){
            b_list = prevBuy;
            prevBuy = Calculation;
            Calculation = b_list;
        }
        return gcd(Calculation % prevBuy, prevBuy);
    }
}

