public class Main {

    public static void main(String[] args) {

        Scanner _time = new Scanner(System.in);
        int B_TOTAL = _time.nextInt();
        int nextBigInteger = 0;
        for(int built= 0;built<B_TOTAL;built++){
            for(int sum_time= 0 ;sum_time<B_TOTAL;sum_time++){
                for(int safeSort= 0;safeSort<B_TOTAL;safeSort++){
                    nextBigInteger = nextBigInteger + mgcd(built+1,sum_time+1,safeSort+1);
                }
            }
        }
        System.out.println(nextBigInteger);
    }

    public static final int mgcd(int built, int sum_time, int safeSort) {
        int g = gcd(built,sum_time);
        g = gcd(g,safeSort);
    return g;
    }

    public static final int gcd(int built, int sum_time) {

        if (built < sum_time) {
            int tmp = built;
            built = sum_time;
            sum_time = tmp;
        }

        int r = -1;
        while (r != 0) {
            r = built % sum_time;
            built = sum_time;
            sum_time = r;
        }

        return built;
    }


}

