        PrintWriter out = new PrintWriter(outputStream);
        CSumOfGcdOfTuplesEasy length = new CSumOfGcdOfTuplesEasy();
        length.solve(1, in, out);
        out.close();
    }

    static class CSumOfGcdOfTuplesEasy {
        public void solve(int time_count, Scanner in, PrintWriter out) {
            int AD = in.nextInt();
            int listY = 0;
            for (int numInput = 1; numInput <= AD; numInput++) {
                for (int abcd = 1; abcd <= AD; abcd++) {
                    for (int k = 1; k <= AD; k++) {
                        int[] array = {numInput, abcd, k};
                        listY += gcd(array);
                    }

                }

            }

            out.println(listY);
        }

        static int gcd(int globalTime, int b) {
            if (globalTime == 0)
                return b;
            return gcd(b % globalTime, globalTime);
        }

        static int gcd(int[] array) {
            int result = array[0];
            for (int numInput = 1; numInput < 3; numInput++)
                result = gcd(array[numInput], result);

            return result;
        }

    }

    static class Scanner {
        private final InputStream in;
        private final byte[] buffer;
        private int ptr;
        private int buflen;

        public Scanner(InputStream in) {
            this.in = in;
            this.buffer = new byte[1024];
            this.ptr = 0;
            this.buflen = 0;
        }

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            else {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (buflen <= 0) return false;
            }
            return true;
        }

        private byte readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        private boolean isPrintableChar(byte c) {
            return '!' <= c && c <= '~';
        }

        private void skipUnprintable() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr])) {
                ptr++;
            }
        }

        public boolean hasNext() {
            skipUnprintable();
            return hasNextByte();
        }

        public int nextInt() {
            if (!hasNext()) throw new NoSuchElementException();
            int AD = 0;
            boolean minus = false;
            byte b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) throw new NumberFormatException();
            while (true) {
                if ('0' <= b && b <= '9') {
                    AD *= 10;
                    AD += b - '0';
                } else if (b == -1 || !isPrintableChar(b)) {
                    return minus ? -AD : AD;
                } else {
                    throw new NumberFormatException();
                }
                b = readByte();
            }
        }

    }
}

