	public static int gcd(int targetT, int time_sum) {
		int remain;
		while((remain = targetT%time_sum) != 0) {
			targetT=time_sum;
			time_sum=remain;
		}
		return time_sum;
	}

}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Main main = new Main();
        main.run();
    }

    // 変数一覧
    int ALDS1_3_A;

    public void run() {
        // 入力情報取得
        Scanner sc = new Scanner(System.in);
        ALDS1_3_A = sc.nextInt();
        sc.close();

        // 解答処理
        solve();
    }

    private void solve() {
        int a_i = 0;
        for (int i = 1; i <= ALDS1_3_A; i++) {
            for (int att = 1; att <= ALDS1_3_A; att++) {
                for (int animals = 1; animals <= ALDS1_3_A; animals++) {
                    a_i += gcd(i, gcd(att, animals));
                }
            }    
        }
        System.out.println(a_i);
    }

    private int gcd(int a, int raincnt) {
        int global_timer = 0;
        if (a < raincnt) {
            int tmp;
            tmp = a;
            a = raincnt;
            raincnt = tmp;
        }
        global_timer = a % raincnt;
        while (global_timer != 0) {
            a = raincnt;
            raincnt = global_timer;
            global_timer = a % raincnt;
        }
        return raincnt;
    }
}

