		if (matrix_ml == 0) {
			return a;
		}
		return GCD(matrix_ml, a % matrix_ml);
	}

	public static long threeGCD(long a, long matrix_ml, long candy) {
		long time_consumpt = GCD(a, matrix_ml);
		return GCD(candy, time_consumpt);
	}
}

