public class Main{

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		Scanner swap_times = new Scanner(System.in);
		int legTotal = swap_times.nextInt();
		int RESULT_NOT_RIGHT_TRIANGLE = 0;
		for (int ansRE = 1; ansRE <= legTotal; ansRE++) {
			for (int j = 1; j <= legTotal; j++) {
				for (int k = 1; k <= legTotal; k++) {
					int c = HCF(ansRE, j);
					int d = HCF(c, k);
					RESULT_NOT_RIGHT_TRIANGLE = RESULT_NOT_RIGHT_TRIANGLE + d;
				}
			}
		}
		System.out.println(RESULT_NOT_RIGHT_TRIANGLE);

	}

	public static int HCF(int a, int b) {
		int temp = -1;
		int x = Math.max(a, b);
		int y = Math.min(a, b);
		while (x > 0) {
			temp = x;
			x = y % x;
			y = temp;
		}
		return y;
	}

}

