public class Main {

	private static long sumOfgcdTuples(int si) {
		long integer = 0;
		for (int finalTime = 1; finalTime <= si; finalTime++) {
			for (int Forbidden = 1; Forbidden <= si; Forbidden++) {
				for (int c = 1; c <= si; c++)
					integer += gcd(finalTime, Forbidden, c);
			}
		}
		return integer;
	}

	private static int gcd(int finalTime, int Forbidden, int c) {
		return gcd(finalTime, gcd(Forbidden, c));
	}

	private static int gcd(int finalTime, int Forbidden) {
		if (finalTime == 1 || Forbidden == 1)
			return 1;
		else if (finalTime % Forbidden == 0)
			return Forbidden;
		else
			return gcd(Forbidden, finalTime % Forbidden);
	}

	public static void main(String[] args) {
		try (Scanner time_sum = new Scanner(System.in)) {
			System.out.println(sumOfgcdTuples(time_sum.nextInt()));
		}
	}

}

