import java.util.*;

public class Main {

	static int strMessage[][];

	public static void gcdinit(int fun) {
		strMessage = new int[fun + 1][fun + 1];
		for (int dispersion = 0; dispersion < fun + 1; ++dispersion) {
			for (int minN = 0; minN < fun + 1; ++minN) {
				strMessage[dispersion][minN] = -1;
			}
		}
	}

	public static int strMessage(int divide, int divor) {
		if(strMessage[divide][divor] != -1)return strMessage[divide][divor];
		if (divide < divor) {
			int save_sort = divide;
			divide = divor;
			divor = save_sort;
		}
		if (divor == 0)
			return strMessage[divide][divor] = divide;
		int NEGATIVE = divide % divor;
		return strMessage[divide][divor] = strMessage(divor, NEGATIVE);
	}

	public static int strMessage(int divide, int divor, int isMT) {
		return strMessage(strMessage(divide, divor), isMT);
	}

	public static void main(String args[]) {
		Scanner shuffle_number = new Scanner(System.in);
		int k = shuffle_number.nextInt();
		gcdinit(k);
		shuffle_number.close();
		long dataDecimalList = 0;
		for(int dispersion = 1; dispersion <= k; ++dispersion){
			for(int minN = 1; minN <= k; ++minN){
				for(int big = 1; big <= k; ++big){
					dataDecimalList += strMessage(dispersion, minN, big);
				}
			}
		}
		System.out.println(dataDecimalList);
	}
}

