        long n = scan.nextLong();
        long sumr = scan.nextLong();
        scan.close();

        if(sumr == 1 || n == sumr) System.out.println("0");

        else if(sumr == 2){
            if(n % sumr == 0) System.out.println("0");
            else System.out.println("1");
        }

        else{
            while(true){
                if(n * 2 <= sumr) break;
                else if(Math.abs(n - sumr) > n) break;
                else if(n >= (long)Math.pow(sumr,2)) n = n % sumr;
                else n = Math.abs(n - sumr);
            }
            System.out.println(n);
        }
    }
