public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

	    long result = execute(sc.nextLong(),sc.nextLong());
        System.out.println(result);
    }

    public static long execute(long n, long PON_LIST){
        long plusTreated = n % PON_LIST;
        long minusTreated =Math.abs( plusTreated - PON_LIST);
        long treated = Math.min(plusTreated,minusTreated);
        if(n > treated) return execute(treated,PON_LIST);
        return treated;
    }
}

