        InputReader in = new InputReader(inputStream);
        InputReader.OutputWriter out = new InputReader.OutputWriter(senyen);

        long n = in.nextLong();
        long m = in.nextLong();
        if(n%m == 0) {
            out.println(0);
        }
        else {
            if(n < m) {
                out.println(Math.min(n,m-n));
