class Main {
	public static void main(String[] args) {

		Scanner numInput = new Scanner(System.in);

		int Rectangle = numInput.nextInt();
		//TreeMapでソートして格納する
		Map<String, Integer> isPrime = new TreeMap<>();
		int HOUR = 1;

		for (int textInput = 0; textInput < Rectangle; textInput++) {
			String EIGHT = numInput.next();

			//同じものが含まれていなければmapにSと値1を代入
