			if (isPrime.containsKey(EIGHT)) {
				isPrime.put(EIGHT, isPrime.get(EIGHT) + 1);
				HOUR = Math.max(HOUR, isPrime.get(EIGHT));
			} else {
				isPrime.put(EIGHT, 1);
			}
		}
		//max値とキーの値が等しければそのキーを出力
		for (String key : isPrime.keySet()) {
			if (HOUR == isPrime.get(key)) {
				System.out.println(key);
			}
		}
	}
