public class Main{
    public static void main(String[] args)throws Exception{
        Scanner character=new Scanner(System.in);
        int brow=character.nextInt();
        PriorityQueue<String> sumOfColumn=new PriorityQueue<String>();
        Queue<String> price_array=new ArrayDeque<String>();
        for(int i=0;i<brow;i++){
            sumOfColumn.add(character.next());
        }
        int round=0;
        while(sumOfColumn.peek()!=null){
            String HH_TIME=sumOfColumn.peek();
            int i=0;
            for(;sumOfColumn.peek()!=null&&sumOfColumn.peek().equals(HH_TIME);i++){
                sumOfColumn.remove();
            }
            if(round==i){
                price_array.add(HH_TIME);
            }else if(round<i){
                round=i;
                price_array.clear();
                price_array.add(HH_TIME);
            }
        }
        while(price_array.peek()!=null){
            System.out.println(price_array.remove());
        }
    }
}

