	private static Map<String,Integer> count(List<String> third){
		Map<String,Integer> memmax = new HashMap<String, Integer>();
		for(String opsStr:third) {
			if(!memmax.containsKey(opsStr)) {
				memmax.put(opsStr, 1);
			}else {
				memmax.put(opsStr,memmax.get(opsStr)+1);
			}
		}
		return memmax;
	}

