		ArrayList<String> objChar1 = null;
		Integer maxVal = 0;
		for(Entry<String, Integer> e: memmax.entrySet()) {
			if(e.getValue().compareTo(maxVal)>0) {
				objChar1 = new ArrayList<String>();
				objChar1.add(e.getKey());
				maxVal = e.getValue();
			}else if(e.getValue().equals(maxVal)) {
				objChar1.add(e.getKey());
			}
		}
		Collections.sort(objChar1);

		for(String opsStr: objChar1) {
			System.out.println(opsStr);
		}
	}

