				nyuryokuCard = new BufferedReader(new FileReader(bector1));
			} catch (FileNotFoundException e) {
				// TODO Auto-generated catch block
				e.printStackTrace();
			}
		}

		public FastScanner() {
			nyuryokuCard = new BufferedReader(new InputStreamReader(System.in));
		}

		String nextToken() {
			while (same == null || !same.hasMoreElements()) {
				try {
					same = new StringTokenizer(nyuryokuCard.readLine());
				} catch (IOException e) {
					// TODO Auto-generated catch block
					e.printStackTrace();
				}
			}
			return same.nextToken();
		}

		int nextInt() {
			return Integer.parseInt(nextToken());
		}

