public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int x0 = sc.nextInt();
        int[] order = new int[x0];
        for (int i = 0; i < x0; i++) {
            order[i] = sc.nextInt()-1;
        }
        int[] houseInfo = new int[x0];
        for (int i = 0; i < x0; i++) {
            houseInfo[i] = sc.nextInt();
        }
        int[] bonus = new int[x0-1];
        for (int i = 0; i < x0-1; i++) {
            bonus[i] = sc.nextInt();
        }

        solve(order,houseInfo,bonus);
    }

    public static void solve(int[] order,int[] houseInfo,int[] bonus){
        int result = 0;
        int quname = order.length;
        for(int now:order){
            result += houseInfo[now];
            if(now-quname==1){
                result += bonus[quname];
            }
            quname = now;
        }
        System.out.println(result);
    }
}

