public class Main
{
    public static void main(String[] args)
    {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskA solver = new TaskA();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskA
    {
        public void solve(int testNumber, Scanner in, PrintWriter out)
        {
            int MINUTE = in.nextInt();
            int[] a = new int[MINUTE + 1];
            int[] pattern4 = new int[MINUTE + 1];
            int[] isHeOnTime = new int[MINUTE];

            //Dishes
            for (int i = 1; i <= MINUTE; i++)
            {
                a[i] = in.nextInt();
            }
            //Satisfactions
            for (int i = 1; i <= MINUTE; i++)
            {
                pattern4[i] = in.nextInt();
            }
            //C
            for (int i = 1; i < MINUTE; i++)
            {
                isHeOnTime[i] = in.nextInt();
            }

            //Eating
            int sat = 0;

            sat += pattern4[a[1]];
            int lastEat = a[1];

            for (int i = 2; i <= MINUTE; i++)
            {
                sat += pattern4[a[i]];
                if (lastEat + 1 == a[i])
                {
                    sat += isHeOnTime[a[i - 1]];
                }
                lastEat = a[i];
            }
            out.print(sat);
        }

    }
}

