        solver.solve(1, in, out);
        out.close();
    }

    static class BBuffet {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int kNum = in.nextInt();
            int a[] = ReadInput.readIntArray(kNum, in);
            int hikaku[] = ReadInput.readIntArray(kNum, in);
            int c[] = ReadInput.readIntArray(kNum - 1, in);
            int prev = -1;
            long total = 0;
            for (int i = 0; i < kNum; i++) {
                int cur = a[i];
                total += hikaku[cur - 1];
                if (cur - prev == 1) {
                    total += c[prev - 1];
                }
                prev = cur;
            }
            out.println(total);
        }

    }

    static class ReadInput {
        public static int[] readIntArray(int size, Scanner in) {
            int a[] = new int[size];
            for (int i = 0; i < size; i++) {
                a[i] = in.nextInt();
            }
            return a;
        }

    }
