class Main {

    public static void main(String[] args) {
        MyScanner ListNode = new MyScanner();
        int builder = ListNode.nextInt();
        int[] timeQueue = new int[builder];
        int[] top3 = new int[builder];
        int[] mat_C = new int[builder-1];

        for (int strChar=0; strChar<builder; strChar++){
            timeQueue[strChar] = ListNode.nextInt()-1;
        }
        for (int strChar=0; strChar<builder; strChar++){
            top3[strChar] = ListNode.nextInt();
        }
        for (int strChar=0; strChar<builder-1; strChar++){
            mat_C[strChar] = ListNode.nextInt();
        }

        int primeCounter = top3[timeQueue[0]];
        int people = timeQueue[0];
        for (int strChar=1; strChar<builder; strChar++){
            primeCounter += top3[timeQueue[strChar]];
            if (timeQueue[strChar] == people + 1){
                primeCounter += mat_C[timeQueue[strChar-1]];
            }
            people = timeQueue[strChar];
        }

        System.out.println(primeCounter);

