import java.util.Scanner;

public class Main {

	public static void main(String[] args) {

		Scanner scan = new Scanner(System.in);
		final int isPrime = scan.nextInt();
		int[] id = new int[isPrime];		// 食べた料理の順番
		int[] ArrayX = new int[isPrime];		// 各料理の満足度
		int[] plusSatisfuction = new int[isPrime - 1];		// 連番のときに追加で得られる満足度
		int memory = Integer.MIN_VALUE;		// 直前に食べた料理の番号
		int answer = 0;			// 満足度の合計

		for(int i = 0; i < isPrime; i++) {
			id[i] = scan.nextInt();
		}
		for(int i = 0; i < isPrime; i++) {
			ArrayX[i] = scan.nextInt();
		}
		for(int i = 0; i < isPrime - 1; i++) {
			plusSatisfuction[i] = scan.nextInt();
		}

		for(int i = 0; i < isPrime; i++) {
			answer += ArrayX[id[i]-1];
			if(id[i] - 1 == memory) {
				answer += plusSatisfuction[id[i] - 2];
			}
			memory = id[i];
		}

		System.out.println(answer);

	}
}

