public class Main {
    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        int zz = sc.nextInt();
        int[] str_a = new int[zz], B = new int[zz], pattern4 = new int[zz];
        for (int i=0; i<zz; i++) {
            str_a[i] = sc.nextInt();
        }
        for (int i=0; i<zz; i++) {
            B[i] = sc.nextInt();
        }
        for (int i=0; i<zz-1; i++) {
            pattern4[i] = sc.nextInt();
        }
        int answerProcessesIndex = 0;
        for (int i=0; i<zz; i++) {
            answerProcessesIndex += B[str_a[i]-1];
            if (i>0 && str_a[i-1] == (str_a[i]-1)) {
                answerProcessesIndex += pattern4[str_a[i-1]-1];
            }
        }
        System.out.println(answerProcessesIndex);
    }
    static class FastReader
    {
        BufferedReader br;
        StringTokenizer st;
        public FastReader(InputStream x) {
            br = new BufferedReader(new
                    InputStreamReader(x));

        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                }
                catch (IOException e)
                {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt()
        {
            return Integer.parseInt(next());
        }

        long nextLong()
        {
            return Long.parseLong(next());
        }

        double nextDouble()
        {
            return Double.parseDouble(next());
        }

        String nextLine()
        {
            String str = "";
            try
            {
                str = br.readLine();
            }
            catch (IOException e)
            {
                e.printStackTrace();
            }
            return str;
        }
    }
}

