import java.util.Scanner;

class Solver {
    void solve(Scanner sc) {
        int sh_str = sc.nextInt();
        int[] LCD = new int[sh_str];
        int[] strInput = new int[sh_str];
        int[] C = new int[sh_str - 1];
        for (int i = 0; i < LCD.length; i++) {
            LCD[i] = sc.nextInt() - 1;
        }
        for (int i = 0; i < strInput.length; i++) {
            strInput[i] = sc.nextInt();
        }
        for (int i = 0; i < C.length; i++) {
            C[i] = sc.nextInt();
        }
        int bufferPointer = strInput[LCD[0]];
        for (int i = 1; i < sh_str; i++) {
            int prev = LCD[i - 1];
            int next = LCD[i];
            if (prev + 1 == next) bufferPointer += C[prev];
            bufferPointer += strInput[next];
        }
        System.out.println(bufferPointer);
    }
}

class Main {
    public static void main(String... args) {
        Scanner in = new Scanner(System.in);

        new Solver().solve(in);

        in.close();
    }
}

