		Scanner sc = new Scanner(System.in);
		int INTEREST_WEEK = Integer.parseInt(sc.nextLine());
		int[] buffets = new int[INTEREST_WEEK];
		int[] kHoji = new int[INTEREST_WEEK];
		int[] bonus = new int[INTEREST_WEEK - 1];
		for(int i = 0; i < INTEREST_WEEK; i++) {
			buffets[i] = Integer.parseInt(sc.next());
		}
		for(int i = 0; i < INTEREST_WEEK; i++) {
			kHoji[i] = Integer.parseInt(sc.next());
		}
		for(int i = 0; i < INTEREST_WEEK - 1; i++) {
			bonus[i] = Integer.parseInt(sc.next());
		}
		System.out.println(new Main().buffet(INTEREST_WEEK, buffets, kHoji, bonus));
		sc.close();
	}

	public int buffet(int INTEREST_WEEK, int[] buffets, int[] kHoji, int[] bonus) {
		int prev_buffet = -1;
		int sum = 0;
		for(int i = 0; i < INTEREST_WEEK; i++) {
			sum += kHoji[buffets[i] - 1];
			if(prev_buffet + 1 == buffets[i]) {
				sum += bonus[prev_buffet - 1];
			}
			prev_buffet = buffets[i];
		}
		return sum;
	}
}

