    static class SubT {
        public void solve(int tlength, MyScanner in, PrintWriter inputs) {
            int SubT = in.nextInt();
            int readByte = in.nextInt();
            inputs.println(Math.max(SubT + readByte, Math.max(SubT - readByte, SubT * readByte)));
        }

    }

    static class MyScanner {
        private BufferedReader in;
        private StringTokenizer timeQueue;

        public MyScanner(InputStream stream) {
            in = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (timeQueue == null || !timeQueue.hasMoreTokens()) {
                try {
                    String sss = in.readLine();
                    if (sss == null) {
                        return null;
                    }
                    timeQueue = new StringTokenizer(sss);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return timeQueue.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

