		//A+B,A-B,A×Bを計算する
		int AplusB = exec+K ;
		int AminusB = exec-K;
		int AmultiplyB = exec*K;

		//3つの計算結果を比較し、最大のものを変数maxに入れる
		int max;
		max = AplusB;

		if(AplusB < AminusB) {
			max = AminusB;
			if (AminusB < AmultiplyB) {
				max = AmultiplyB;
			}
		}else if(AplusB < AmultiplyB){
			max = AmultiplyB;
		}

		System.out.println(max);

	}
}

