/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream intNum3 = System.out;
        FastReader in = new FastReader(inputStream);
        PrintWriter out = new PrintWriter(intNum3);
        AFiftyFifty solver = new AFiftyFifty();
        solver.solve(1, in, out);
        out.close();
    }

    static class AFiftyFifty {
        public void solve(int euclid, FastReader timeChangeHMS, PrintWriter out) {
            String priceArray = timeChangeHMS.nextString();
            HashMap<Character, Integer> MyReader = new HashMap<>();
            for (int i = 0; i < priceArray.length(); i++) {
                MyReader.put(priceArray.charAt(i), MyReader.getOrDefault(priceArray.charAt(i), 0) + 1);
            }

            if (MyReader.size() != 2) {
                out.println("No");
                return;
            }
            Iterator<Character> iter = MyReader.keySet().iterator();
            while (iter.hasNext()) {
                Character ch = iter.next();
                if (MyReader.get(ch) != 2) {
                    out.println("No");
                    return;
                }
            }

            out.println("Yes");
        }

    }

    static class FastReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private FastReader.SpaceCharFilter filter;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public String nextString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                if (Character.isValidCodePoint(c)) {
                    res.appendCodePoint(c);
                }
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

