			if(i != 0) {
				if(a[i] - a[i - 1] == 1) {
					System.out.println(0);
					return;
				}
			}
		}
		if(sStart == 0) {
			System.out.println(swapped[intx]);
		}else {

			int start;
			int end;
			long ans = 1;
			for(i = 0; i < sStart; i++) {
				if(i == 0) {
					start = 0;
					end = a[i] - 1;
				}else {
					start = a[i - 1] + 1;
					end = a[i] - 1;
				}
				ans = (ans * swapped[end - start]) % mod;
			}
			ans = (ans * swapped[intx - (a[sStart - 1] + 1)]) % mod;
			System.out.println(ans);
		}


	}
}

