public static void main(String[] args) {

		Scanner keyboard = new Scanner(System.in); 

		String method = keyboard.next();
			int elementIndex = Integer.parseInt(method);

		int[] x_ = new int[elementIndex];
			for(int i=0; i < elementIndex; i++) {
				x_[i] = keyboard.nextInt();
			}

		int count = 1;

		int max = x_[0];
		int min = 0;

		if (elementIndex > 1) {
			min = x_[1];
		}

		for (int j = 1; j < elementIndex; j++) {
		    int height = x_[j];
		    if ( height >= max) {
		        max = height;
		        count ++;
		        continue;
		    }else {
		    	if (height < min) {
		    		min = height;
		    		continue;
		    	}
		    }
		}
			System.out.print(count);

		keyboard.close();	
	}
}

