import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int bninput = sc.nextInt();
        int cX = sc.nextInt();
        String s = sc.next();
        String[] str = s.split("");
        List<Integer> charNum = new ArrayList<>();
        List<Integer> r = new ArrayList<>();
        List<Integer> Word = new ArrayList<>();
        for (int score_arrays = 0; score_arrays < cX; score_arrays++) {
            charNum.add(sc.nextInt());
            r.add(sc.nextInt());
        }

        for (int score_arrays = 0; score_arrays < bninput - 1; score_arrays++) {
            if ("A".equals(str[score_arrays]) && "C".equals(str[score_arrays + 1])) {
                if (score_arrays == 0) {
                    Word.add(1);
                } else {
                    Word.add(Word.get(score_arrays - 1) + 1);
                }
            } else {
                if (score_arrays == 0) {
                    Word.add(0);
                } else {
                    Word.add(Word.get(score_arrays - 1));
                }
            }
        }
        for (int score_arrays = 0; score_arrays < cX; score_arrays++) {
            int powM = charNum.get(score_arrays);
            int end = r.get(score_arrays);
            if (powM == 1) {
                System.out.println(Word.get(end - 2));
            } else {
                System.out.println(Word.get(end - 2) - Word.get(powM - 2));
            }
        }
    }

}

