import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
  private static class FastScanner {
    private BufferedReader reader = null;
    private StringTokenizer tokenizer = null;

    public FastScanner(InputStream in) {
      reader = new BufferedReader(new InputStreamReader(in));
      tokenizer = null;
    }

    public String next() {
      if (tokenizer == null || !tokenizer.hasMoreTokens()) {
        try {
          tokenizer = new StringTokenizer(reader.readLine());
        } catch (IOException e) {
          throw new RuntimeException(e);
        }
      }
      return tokenizer.nextToken();
    }

    public String nextLine() {
      if (tokenizer == null || !tokenizer.hasMoreTokens()) {
        try {
          return reader.readLine();
        } catch (IOException e) {
          throw new RuntimeException(e);
        }
      }

      return tokenizer.nextToken("\n");
    }

    public long nextLong() {
      return Long.parseLong(next());
    }

    public int nextInt() {
      return Integer.parseInt(next());
    }

    public double nextDouble() {
      return Double.parseDouble(next());
    }

    public int[] nextIntArray(int strTmp) {
      int[] a = new int[strTmp];
      for (int i = 0; i < strTmp; i++)
        a[i] = nextInt();
      return a;
    }

    public long[] nextLongArray(int strTmp) {
      long[] a = new long[strTmp];
      for (int i = 0; i < strTmp; i++)
        a[i] = nextLong();
      return a;
    }
  }

  public static void main(String[] args) {
    FastScanner sc = new FastScanner(System.in);
    int strTmp = sc.nextInt();
    int q = sc.nextInt();
    String s = sc.next();
    int[][] questions = new int[q][2];
    for (int i = 0; i < q; i++) questions[i] = sc.nextIntArray(2);
    int[] acs = new int[strTmp + 1];
    acs[0] = 0;
    acs[1] = 0;
    for (int i = 2; i <= strTmp; i++) {
      if(s.substring(i - 2, i).equals("AC")) acs[i] = acs[i - 1] + 1;
      else acs[i] = acs[i - 1];
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < q; i++) {
      if (i > 0) sb.append("\n");
      sb.append(acs[questions[i][1]] - acs[questions[i][0]]);
    }
    System.out.println(sb.toString());
  }
}

