public class Main {
	public static int gcd(int a,int b) {
		while(true) {
			a%=b;
			if(a==0)return b;
			b%=a;
			if(b==0)return a;
		}
	}
	public static void main(String[] args) throws IOException{
		BufferedReader re=new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer t=new StringTokenizer(re.readLine());
		int a=Integer.parseInt(t.nextToken()),b=Integer.parseInt(t.nextToken()),isRange=Integer.parseInt(t.nextToken());
		int c=gcd(a,b),d=c;
		while(isRange>1) {
			if(c%--d==0)--isRange;
		}
		System.out.println(d);
	}
}

import java.util.*;

public class Main {
    //K-th Common Divisor
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt(), getY = sc.nextInt(), SumDigit = sc.nextInt();
        System.out.println(helper(a, getY, SumDigit));
        sc.close();
    }

    public static int helper(int a, int getY, int SumDigit) {
        int count = 0;
        for (int i = Math.min(a, getY); i >= 1; i--) {
            if (a % i == 0 && getY % i == 0) count++;
            if (count == SumDigit) return i;
        }
        return 0;
    }
}

