public class Main {
    private static long[] Vec_A;
    private static long cost(int Show, int[] meTime, int choice){
        if(Show >= meTime.length) return Long.MAX_VALUE;
        if(Show == meTime.length - 1) return 0;
        if(Vec_A[Show] != -1) return Vec_A[Show];
        long tensu = Long.MAX_VALUE;
