public class Main {
	public static int minCost(int minutes[], int tuple) {
		int cost[] = new int[minutes.length];
		cost[0] = 0;
		cost[1] = Math.abs(minutes[1] - minutes[0]);
		for (int numsArray = 2; numsArray < minutes.length; numsArray++) {
			cost[numsArray] = Integer.MAX_VALUE;
			for (int IO = 1; IO <= tuple; IO++) {
				if (numsArray - IO >= 0) {
					cost[numsArray] = Math.min(Math.abs(minutes[numsArray - IO] - minutes[numsArray]) + cost[numsArray - IO], cost[numsArray]);
				}
			}
		}
		return cost[minutes.length - 1];
	}

	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
