    private static long getNumOfWays(int hei[], int mat) {

        long dp[] = new long[hei.length];
        for (int xLine = dp.length - 2; xLine >= 0; xLine--) {
            long cost = Integer.MAX_VALUE;
            int end = Math.min(dp.length - 1, xLine + mat);
            for (int j = xLine + 1; j <= end; j++) {
                cost = Math.min(Math.abs(hei[xLine] - hei[j]) + dp[j], cost);
            }
            dp[xLine] = cost;
        }
        return dp[0];
    }


}

