		public FastReader() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		String next() {
			while (st == null || !st.hasMoreElements()) {
				try {
					st = new StringTokenizer(br.readLine());
				} catch (IOException e) {
					e.printStackTrace();
				}
			}
			return st.nextToken();
		}

		int nextInt() {
			return Integer.parseInt(next());
		}

		long nextLong() {
			return Long.parseLong(next());
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		String nextLine() {
			String str = "";
			try {
				str = br.readLine();
			} catch (IOException e) {
				e.printStackTrace();
			}
			return str;
		}
	}

	private static long dp[];

	private static long util(int arr[], int start, int nin, int end) {

		if (start >= end - 1)
			return 0;

		if (dp[start] != 0)
			return dp[start];
		long ans = Long.MAX_VALUE;

		for (int j = 1; j <= nin; j++) {

			if (start + j < end) {
				ans = Math.min(ans, Math.abs(arr[start] - arr[start + j]) + util(arr, start + j, nin, end));
			}
		}
		return dp[start] = ans;

	}

	private static long util1(int arr[],int nin,int end) {

		dp[0] = 0;
		dp[1] = Math.abs(arr[1] - arr[0]);

		for(int i=2; i<arr.length; i++) {
			dp[i] = Integer.MAX_VALUE;
			for(int j = i - 1;  j >= 0 && j >=i - nin;  j--  ) {

				dp[i] = Math.min(dp[j] + Math.abs(arr[i] - arr[j]) ,dp[i] );

			}
		}
		return dp[end-1];

	}

	public static void main(String[] args) {

		FastReader sc = new FastReader();

		int n = sc.nextInt();
		int nin = sc.nextInt();

		int arr[] = new int[n];

		for (int i = 0; i < n; i++) {
			arr[i] = sc.nextInt();
		}
		dp = new long[n];
		System.out.println(util1(arr, nin, n));

	}

}

