public class Main {
  public static void main(String[] args) {


    Scanner sc = new Scanner(System.in);
    // get a integer

    int suitnum = sc.nextInt();
//    System.out.println(" integer is " + N);
    List<Integer> aList = new ArrayList<>();
    List<Integer> lowerStr = new ArrayList<>();
    int Y = sc.nextInt();
    int ansx = -1, ansy = -1, ansz = -1;
//    Y = 10000 * x + 5000 * y + 1000 *z;
//    N = x + y + z;
//    z = N - x - y;
//    z = (Y - (10000 * x + 5000 * y)) /1000;


    for(int x = 0; x <= suitnum ; x++){
      // i is equal to x
      double caluculatedY = getCalY(x, suitnum,  Y);
      double caluculatedZ = suitnum -x - caluculatedY;
      if(validateAll(caluculatedY,caluculatedZ, suitnum)){
        ansx = x;
        ansy = (int)caluculatedY;
        ansz = (int)caluculatedZ;
        break;
      }
    }
    System.out.println(ansx + " " + ansy + " " + ansz);

  };
  private static double getCalY(int x,int suitnum, int Y) {
//    Y = 10000 * x + 5000 * y + 1000 * (N - x - y);
//    Y = 10000 * x + 5000 * y + 1000 *N - 1000* x - 1000* y;
//    Y = 9000*x + 4000*y + 1000*N
//
    double y = ((double)Y - 9000 * (double)x  - 1000* (double)suitnum ) /4000;
    return y;
  }

  public static boolean validate(double a, double suitnum) {
    if(a ==(int)a && a >= 0 && a <= suitnum){
      return true;
    }else{
      return false;
    }
  }
  public static boolean validateAll(double y, double z, int suitnum) {
    boolean yflag = false, zflag = false;
    if(validate(y, suitnum)){
      yflag = true;
    };
    if(validate(z, suitnum)){
      zflag = true;
    }
    return yflag && zflag;
  }
}

