import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

class Main {
  public static void main(String[] args) throws IOException{
    BufferedReader bf = new BufferedReader(new InputStreamReader(System.in));
    String input = bf.readLine();
    System.out.println(check(input));
    bf.close();
  }
  static String check(String chain){
    //文字列sの最初の文字について、偶数個あったら、trueを返す。
    if (chain.length() == 0) {
      return "Yes";
    }
    char[] bMatrix = chain.toCharArray();
    char mx3 = bMatrix[0];
    int quanTime = 0;
    StringBuilder sb = new StringBuilder();
    for (char c : bMatrix) {
      if (c == mx3) {
        quanTime++;
      } else {
        sb.append(c);
      }
    }
    if (quanTime % 2 == 0) {
      return check(sb.toString());
    } else {
      return "No";
    }
  }
}

import java.util.*;

public class Main {
  public static void main(String[] args) {
    Scanner s = new Scanner(System.in);
    String AC = s.nextLine();
    boolean ans = solve(AC);
    if(ans)
      System.out.println("Yes");
    else
      System.out.println("No");
  }

  public static boolean solve(String AC){
    boolean ans = true;
    int even = 0;
    for(int i = 0; i < AC.length() ; i++){
      for(int j = 0; j < AC.length() ; j++){
        if(AC.charAt(i) == AC.charAt(j))
          even += 1;
      }
      if(even % 2 != 0 ){
        ans = false;
        break;
      }
    }
    return ans;
  }
}

