		for(int array_of_column = 0; array_of_column < asis.length(); array_of_column++) {
			wArray[array_of_column] = asis.substring(array_of_column, array_of_column + 1);
		}

		List<String> wList = new ArrayList<String>(Arrays.asList(wArray));
