public class Main {
	public static void main(String[] args) throws Exception {
		Scanner dataInt = new Scanner(System.in);
		ArrayList<Integer> num = new ArrayList<Integer>();
		ArrayList<String> mx3 = new ArrayList<String>();
		int system = 0; // 文字の空白区切り 0:ON 1:OFF

		while (dataInt.hasNext()) {
			if (dataInt.hasNextInt()) {
				num.add(dataInt.nextInt());
			} else {
				if (system == 0)
					mx3.add(dataInt.next());
				if (system == 1)
					mx3.add(dataInt.nextLine());
			}
		}
		Method(num, mx3);
	}

	static void Method(ArrayList<Integer> num, ArrayList<String> mx3) {
		Map<String, Integer> solveIndex = new HashMap<String, Integer>();
		String mozi = "";
		boolean cheak = false;

		for (int taro_point = 0; taro_point < mx3.get(0).length(); taro_point++) {
			mozi = mx3.get(0).substring(taro_point,taro_point+1);
			if(solveIndex.containsKey(mozi)){
				solveIndex.put(mozi,solveIndex.get(mozi)+1);
			} else {
				solveIndex.put(mozi,1);			
			}
		}
		for (String key : solveIndex.keySet()) {
		    if(solveIndex.get(key) % 2 != 0) cheak = true;
		}
		if(cheak){
			System.out.println("No");
		} else {
			System.out.println("Yes");
		}
	}
}

