class Main {
    static class FastReader{
        BufferedReader br;
        StringTokenizer existX;
        public FastReader(){
            br = new BufferedReader(new InputStreamReader(System.in));
        }
        String next(){
            while(existX==null || !existX.hasMoreTokens()){
                try{
                    existX = new StringTokenizer(br.readLine());
                }
                catch(IOException e){
                    e.printStackTrace();
                }
            }
            return existX.nextToken();
        }
        int nextInt(){
            return Integer.parseInt(next());
        }
    }

	public static void main (String[] args) {
		FastReader ob = new FastReader();
	    Stack<String> existX = new Stack<String>();
	    String startTime = ob.next();
	    int n = startTime.length();
	    for (int i=0;i<n ;i++ ) {
	        if(startTime.charAt(i)=='B' && !existX.empty()){
	            existX.pop();
	        }
	        else if(startTime.charAt(i)!='B'){
	            existX.push(""+startTime.charAt(i));
	        }
	    }
	    String ans ="";
	    while(!existX.empty()){
	        ans = existX.pop()+ans;
	    }
	    System.out.print(ans);

	}
}

